#include <stdio.h>
#include <stdlib.h>
#define SIZE 5
int head = 0;
int count = 0;
long items[SIZE];

void enqueue(long item) {
    if (count == SIZE) {
        printf("FULL\n");
        return;
    }
    int tail = (head + count) % SIZE;
    items[tail] = item;
    count++;
    printf("ENQ %ld\n", item);
}

void dequeue() {
    if (count == 0) {
        printf("EMPTY\n");
        return;
    }
    long item = items[head];
    head = (head + 1) % SIZE;
    count--;
    printf("DEQ %ld\n", item);
}

void print_front() {
    if (count == 0) {
        printf("EMPTY\n");
        return;
    }
    printf("FRONT %ld\n", items[head]);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        char *op = argv[i];
        if (op[0] == 'E') {
            long item = strtol(op + 1, NULL, 10);
            enqueue(item);
        } else if (op[0] == 'D') {
            dequeue();
        } else if (op[0] == 'F') {
            print_front();
        } else {
            printf("ERR\n");
        }
    }
    return 0;
}
